PRAGMA foreign_keys=ON;
CREATE TABLE business_settings(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, address TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, whatsapp TEXT NOT NULL);
INSERT INTO business_settings VALUES(1,'Sanjeewa Distribution ERP','Not configured','Not configured','Not configured','Not configured');
CREATE TABLE roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,admin INTEGER NOT NULL DEFAULT 0 CHECK(admin IN (0,1)));
INSERT INTO roles VALUES('admin','Admin',1),('sales_rep','Sales Representative',0),('staff','Staff',0);
CREATE TABLE permissions(key TEXT PRIMARY KEY,description TEXT NOT NULL);
CREATE TABLE role_permissions(role_id TEXT NOT NULL REFERENCES roles(id),permission_key TEXT NOT NULL REFERENCES permissions(key),PRIMARY KEY(role_id,permission_key));
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role_id TEXT NOT NULL REFERENCES roles(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE user_permissions(user_id TEXT NOT NULL REFERENCES users(id),permission_key TEXT NOT NULL REFERENCES permissions(key),allowed INTEGER NOT NULL CHECK(allowed IN(0,1)),PRIMARY KEY(user_id,permission_key));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE products(id TEXT PRIMARY KEY,category_id TEXT REFERENCES categories(id),name TEXT NOT NULL,sku TEXT NOT NULL UNIQUE,barcode TEXT UNIQUE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE product_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),label TEXT NOT NULL,unit TEXT NOT NULL,grams INTEGER CHECK(grams IS NULL OR grams>0),retail_cents INTEGER NOT NULL CHECK(retail_cents>=0),wholesale_cents INTEGER NOT NULL CHECK(wholesale_cents>=0),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),low_stock INTEGER NOT NULL DEFAULT 0 CHECK(low_stock>=0));
CREATE TABLE warehouses(id TEXT PRIMARY KEY,name TEXT NOT NULL,rep_id TEXT UNIQUE REFERENCES users(id));
INSERT INTO warehouses VALUES('main','Main warehouse',NULL);
CREATE TABLE stock_balances(warehouse_id TEXT NOT NULL REFERENCES warehouses(id),variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),PRIMARY KEY(warehouse_id,variant_id));
CREATE TABLE stock_movements(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(id),from_warehouse TEXT REFERENCES warehouses(id),to_warehouse TEXT REFERENCES warehouses(id),quantity INTEGER NOT NULL CHECK(quantity>0),reason TEXT NOT NULL,reference_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE rep_stock_allocations(id TEXT PRIMARY KEY,rep_id TEXT NOT NULL REFERENCES users(id),variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity>0),created_at TEXT NOT NULL);
CREATE TABLE customers(id TEXT PRIMARY KEY,shop_name TEXT NOT NULL,owner_name TEXT NOT NULL,phone TEXT NOT NULL,whatsapp TEXT NOT NULL,address TEXT NOT NULL,location TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('wholesale','retail')),credit_limit_cents INTEGER NOT NULL DEFAULT 0 CHECK(credit_limit_cents>=0),credit_days INTEGER NOT NULL DEFAULT 0 CHECK(credit_days BETWEEN 0 AND 45),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE customer_assignments(customer_id TEXT NOT NULL REFERENCES customers(id),rep_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(customer_id,rep_id));
CREATE TABLE invoices(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL REFERENCES customers(id),rep_id TEXT NOT NULL REFERENCES users(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),total_cents INTEGER NOT NULL CHECK(total_cents>=0),paid_cents INTEGER NOT NULL DEFAULT 0 CHECK(paid_cents>=0 AND paid_cents<=total_cents),status TEXT NOT NULL CHECK(status IN('posted','cancelled')),due_at TEXT,idempotency_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,cancelled_at TEXT);
CREATE INDEX invoices_customer_due ON invoices(customer_id,due_at);
CREATE INDEX invoices_rep_created ON invoices(rep_id,created_at);
CREATE TABLE invoice_items(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),line_cents INTEGER NOT NULL CHECK(line_cents>=0));
CREATE TABLE payments(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),method TEXT NOT NULL CHECK(method IN('cash','bank','other')),idempotency_key TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE credit_terms(customer_id TEXT PRIMARY KEY REFERENCES customers(id),days INTEGER NOT NULL CHECK(days BETWEEN 0 AND 45));
CREATE TABLE reminders(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),type TEXT NOT NULL,due_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(invoice_id,type,due_at));
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_id TEXT,details TEXT,created_at TEXT NOT NULL);
CREATE INDEX audit_created ON audit_logs(created_at);
CREATE TABLE system_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE login_attempts(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window_start TEXT NOT NULL);
CREATE TRIGGER invoices_immutable BEFORE UPDATE OF customer_id,rep_id,warehouse_id,total_cents,due_at,created_at ON invoices BEGIN SELECT RAISE(ABORT,'posted invoice is immutable'); END;
CREATE TRIGGER invoice_items_immutable BEFORE UPDATE ON invoice_items BEGIN SELECT RAISE(ABORT,'invoice items immutable'); END;
CREATE TRIGGER invoice_items_no_delete BEFORE DELETE ON invoice_items BEGIN SELECT RAISE(ABORT,'invoice items immutable'); END;
CREATE TRIGGER payment_limit BEFORE INSERT ON payments BEGIN SELECT CASE WHEN (SELECT status FROM invoices WHERE id=NEW.invoice_id)!='posted' THEN RAISE(ABORT,'invoice not payable') WHEN NEW.amount_cents+COALESCE((SELECT SUM(amount_cents) FROM payments WHERE invoice_id=NEW.invoice_id),0)>(SELECT paid_cents FROM invoices WHERE id=NEW.invoice_id) THEN RAISE(ABORT,'payment exceeds recorded collection') END; END;
CREATE TRIGGER stock_movement_guard BEFORE INSERT ON stock_movements WHEN NEW.from_warehouse IS NOT NULL BEGIN SELECT CASE WHEN COALESCE((SELECT quantity FROM stock_balances WHERE warehouse_id=NEW.from_warehouse AND variant_id=NEW.variant_id),0)<NEW.quantity THEN RAISE(ABORT,'insufficient stock') END; END;
CREATE TRIGGER invoice_credit_guard BEFORE INSERT ON invoices WHEN NEW.total_cents>NEW.paid_cents BEGIN SELECT CASE WHEN (SELECT credit_limit_cents FROM customers WHERE id=NEW.customer_id)<(NEW.total_cents-NEW.paid_cents)+COALESCE((SELECT SUM(total_cents-paid_cents) FROM invoices WHERE customer_id=NEW.customer_id AND status='posted'),0) THEN RAISE(ABORT,'credit limit exceeded') END; END;
